//! Acceptance 1: the six S5a read faces keep the Python shapes.
//!
//! The expected statuses, shapes and stable fields come from
//! `tests/fixtures/rust_console_rev1.json`, generated by
//! `tests/generate_rust_console_fixture.py` from the real Python cloud
//! `usagesrv.Handler`.

mod support;

use std::path::PathBuf;

use rusqlite::types::Value as SqlValue;
use serde_json::{json, Value};

use support::*;
use um_console::runtime::RuntimeSnapshot;
use um_console::ConsoleServer;

fn get(addr: std::net::SocketAddr, target: &str) -> ClientResponse {
    client_request(addr, &ClientRequest::get(target)).expect("request")
}

fn json_to_sql(value: &Value) -> SqlValue {
    match value {
        Value::Null => SqlValue::Null,
        Value::Bool(value) => SqlValue::Integer(i64::from(*value)),
        Value::Number(number) => match number.as_i64() {
            Some(value) => SqlValue::Integer(value),
            None => SqlValue::Real(number.as_f64().unwrap_or_default()),
        },
        Value::String(value) => SqlValue::Text(value.clone()),
        other => SqlValue::Text(other.to_string()),
    }
}

fn seeded_operations(temp: &um_test_harness::TempDataDir, fixture: &Value) -> PathBuf {
    let path = temp.path().join("seeded-console.sqlite3");
    let connection = rusqlite::Connection::open(&path).expect("open seeded state");
    let seeded = &fixture["operations"]["seeded"];
    for ddl in seeded["schema"].as_array().expect("schema") {
        connection
            .execute_batch(ddl.as_str().expect("ddl"))
            .expect("create console schema");
    }
    connection
        .execute(
            "INSERT OR REPLACE INTO console_meta(key, value) VALUES('schema_version', ?)",
            [seeded["metaVersion"].as_str().expect("meta version")],
        )
        .expect("insert console meta");
    let insert = seeded["insertSql"].as_str().expect("insert sql");
    for row in seeded["rows"].as_array().expect("rows") {
        let values: Vec<SqlValue> = row
            .as_array()
            .expect("row")
            .iter()
            .map(json_to_sql)
            .collect();
        connection
            .execute(insert, rusqlite::params_from_iter(values))
            .expect("insert operation row");
    }
    path
}

#[test]
fn health_matches_python() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);
    let response = get(console.addr, "/health");
    assert_eq!(
        u64::from(response.status),
        fixture["health"]["status"].as_u64().unwrap()
    );
    assert_eq!(response.json(), fixture["health"]["body"]);
    assert_eq!(
        response.header("cache-control"),
        fixture["health"]["cache_control"].as_str()
    );
}

#[test]
fn summary_matches_python_cloud_shape() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);
    let response = get(console.addr, "/api/summary");
    let body = response.json();
    assert_eq!(
        u64::from(response.status),
        fixture["summary"]["status"].as_u64().unwrap()
    );
    assert_eq!(shape(&body), fixture["summary"]["shape"]);
    assert_eq!(body["role"], fixture["summary"]["role"]);
    assert_eq!(body["assembly"], fixture["summary"]["assembly"]);
    assert_eq!(body["services"], fixture["summary"]["services"]);
    assert_eq!(body["dsh"], fixture["summary"]["dsh"]);
    assert_eq!(
        body["dshMergedIntoTotal"],
        fixture["summary"]["dshMergedIntoTotal"]
    );
    assert_eq!(body.get("sources"), None);
    assert_eq!(
        shape(&body["_generated_epoch"]),
        fixture["summary"]["generatedEpochType"]
    );
    assert_eq!(
        shape(&body["_cached_age_seconds"]),
        fixture["summary"]["cachedAgeType"]
    );
}

#[test]
fn summary_is_cloud_role_and_does_not_read_a_private_ledger() {
    let fixture = fixture();
    let temp = temp();
    let ledger = temp.path().join("usage-chat2api.jsonl");
    std::fs::write(
        &ledger,
        "{\"model\":\"private-sentinel\",\"input_tokens\":99}
",
    )
    .expect("write private ledger sentinel");
    let console = start_console_with(&temp, stopped_runtime(), |config| {
        // The cloud summary must not carry a private-ledger source at all.
        config.console_state_file = Some(temp.path().join("state.sqlite3"));
    });
    let response = get(console.addr, "/api/summary");
    let body = response.json();
    assert_eq!(response.status, 200);
    assert_eq!(body["role"], fixture["summary"]["role"]);
    assert_eq!(body["assembly"], fixture["summary"]["assembly"]);
    assert_eq!(body["services"], fixture["summary"]["services"]);
    assert_eq!(body["services"], json!({}));
    assert_eq!(body.get("sources"), None);
    assert_eq!(body["dsh"]["url"], Value::Null);
    assert_eq!(body["dshMergedIntoTotal"]["day"], Value::Null);
    assert!(!body.to_string().contains("private-sentinel"));
    assert!(ledger.exists());
}

#[test]
fn services_match_python_shape_and_cache_metadata() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);
    let first = get(console.addr, "/api/console/services");
    let first_body = first.json();
    assert_eq!(
        u64::from(first.status),
        fixture["services"]["status"].as_u64().unwrap()
    );
    assert_eq!(shape(&first_body), fixture["services"]["shape"]);
    assert_eq!(first_body["services"][0], fixture["services"]["service"]);
    assert_eq!(
        first_body["meta"]["source"],
        fixture["services"]["meta"]["source"]
    );
    assert_eq!(
        first_body["meta"]["cached"],
        fixture["services"]["meta"]["firstCached"]
    );

    let second = get(console.addr, "/api/console/services");
    let second_body = second.json();
    assert_eq!(
        second_body["meta"]["cached"],
        fixture["services"]["meta"]["secondCached"]
    );
    assert_eq!(
        shape(&second_body["meta"]["cache_age_seconds"]),
        fixture["services"]["meta"]["secondCacheAgeType"]
    );
}

