#[test]
fn operations_seeded_rows_and_limit_cases_match_python() {
    let fixture = fixture();
    let temp = temp();
    let seeded_path = seeded_operations(&temp, &fixture);
    let console = start_console_with(&temp, stopped_runtime(), |config| {
        config.console_state_file = Some(seeded_path);
    });

    let seeded = get(console.addr, "/api/console/operations");
    assert_eq!(
        u64::from(seeded.status),
        fixture["operations"]["seeded"]["status"].as_u64().unwrap()
    );
    assert_eq!(seeded.json(), fixture["operations"]["seeded"]["body"]);

    let detail = get(console.addr, "/api/console/operations/op-a");
    assert_eq!(
        u64::from(detail.status),
        fixture["operations"]["detail"]["status"].as_u64().unwrap()
    );
    assert_eq!(detail.json(), fixture["operations"]["detail"]["body"]);

    for (query, key) in [
        ("?limit=2", "limit2"),
        ("?limit=0", "limit0"),
        ("?limit=-5", "limitNegative"),
        ("?limit=9999", "limitTooLarge"),
        ("?limit=abc", "limitNonNumeric"),
        ("?limit=", "limitBlank"),
        ("?limit=%2B2", "limitPlus"),
    ] {
        let response = get(console.addr, &format!("/api/console/operations{query}"));
        let case = &fixture["operations"]["limitCases"][key];
        assert_eq!(
            u64::from(response.status),
            case["status"].as_u64().unwrap(),
            "{query}"
        );
        assert_eq!(response.json(), case["body"], "{query}");
    }
}

struct PanicRuntime;

impl um_console::runtime::RuntimeFacts for PanicRuntime {
    fn snapshot(
        &self,
    ) -> Result<um_console::runtime::RuntimeSnapshot, um_console::runtime::RuntimeError> {
        panic!("a cloud capability refusal must not read runtime facts");
    }
}

#[test]
fn non_um_read_faces_are_capability_not_assembled_without_probing() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console_with(&temp, std::sync::Arc::new(PanicRuntime), |_| {});
    for (prefix, case) in fixture["capability"].as_object().unwrap() {
        let response = get(console.addr, &format!("/api/console/{prefix}"));
        assert_eq!(
            u64::from(response.status),
            case["status"].as_u64().unwrap(),
            "{prefix}"
        );
        assert_eq!(response.json(), case["body"], "{prefix}");
    }
    assert_eq!(
        um_console::server::cloud_capability_prefixes().len(),
        fixture["capability"].as_object().unwrap().len()
    );
}

#[test]
fn capability_gate_precedes_the_request_body() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console_with(&temp, std::sync::Arc::new(PanicRuntime), |_| {});
    let response = client_request(
        console.addr,
        &ClientRequest::post("/api/console/stats", b"{\"x\":1}")
            .header("Content-Type", "application/json"),
    )
    .expect("capability post");
    assert_eq!(
        u64::from(response.status),
        fixture["capability"]["stats"]["status"].as_u64().unwrap()
    );
    assert_eq!(response.json(), fixture["capability"]["stats"]["body"]);
}

#[test]
fn gw_usagesrv_alias_matches_native() {
    let fixture = fixture();
    let temp = temp();
    let alias_console = start_console(&temp);
    let alias = get(alias_console.addr, "/gw/usagesrv/api/console/services").json();
    assert_eq!(shape(&alias), fixture["boundary"]["alias"]["shape"]);
    assert_eq!(
        alias["services"][0],
        fixture["boundary"]["alias"]["service"]
    );

    let native_console = start_console(&temp);
    let native = get(native_console.addr, "/api/console/services").json();
    assert_eq!(alias["services"][0], native["services"][0]);
}

#[test]
fn candidate_refuses_production_ports_before_bind() {
    let temp = temp();
    let mut config = base_config(&temp);
    config.bind_port = 8002;
    let error = ConsoleServer::start(config).expect_err("8002 must fail");
    assert!(error.to_string().contains("8002"));

    let mut config = base_config(&temp);
    config.bind_host = "0.0.0.0".to_string();
    let error = ConsoleServer::start(config).expect_err("non-loopback must fail");
    assert!(error.to_string().contains("loopback"));

    let mut config = base_config(&temp);
    config.role = um_console::Role::Local;
    ConsoleServer::start(config).expect("local role must start");
}

#[test]
fn missing_fields_stay_null_or_omitted() {
    let temp = temp();
    let console = start_console_with(&temp, stopped_runtime(), |config| {
        config.console_state_file = None;
    });
    let operations = get(console.addr, "/api/console/operations").json();
    assert_eq!(operations, json!({"operations": []}));

    let summary = get(console.addr, "/api/summary").json();
    assert_eq!(summary["dsh"]["url"], Value::Null);
    assert_eq!(summary["dshMergedIntoTotal"]["day"], Value::Null);
    assert_eq!(summary["services"], json!({}));

    let console = start_console_with(&temp, stopped_runtime(), |config| {
        config.console_state_file = None;
    });
    let body = get(console.addr, "/api/console/operations").json();
    assert_eq!(body["operations"], json!([]));
}

#[test]
fn runtime_snapshot_states_keep_their_python_mapping() {
    let temp = temp();
    let console = start_console_with(
        &temp,
        std::sync::Arc::new(um_console::runtime::StaticRuntimeFacts::new(
            RuntimeSnapshot::conflict("identity mismatch", vec![42]),
        )),
        |_| {},
    );
    let body = get(console.addr, "/api/console/services").json();
    assert_eq!(body["services"][0]["state"], json!("Conflict"));
    assert_eq!(body["services"][0]["healthy"], json!(false));
    assert_eq!(body["services"][0]["process_ids"], json!([42]));
}

#[test]
fn health_payload_reports_unknown_as_unknown_not_stopped() {
    let temp = temp();
    let console = start_console_with(
        &temp,
        std::sync::Arc::new(um_console::runtime::StaticRuntimeFacts::new(
            RuntimeSnapshot::unknown("process liveness undecidable", vec![42]),
        )),
        |_| {},
    );
    let body = get(console.addr, "/api/console/health").json();
    assert_eq!(body["services"][0]["state"], json!("Unknown"));
    assert_eq!(body["services"][0]["healthy"], json!(false));
    assert_eq!(body["services"][0]["process_ids"], json!([42]));
}

#[test]
fn runtime_failure_is_an_honest_502() {
    let temp = temp();
    let console = start_console_with(
        &temp,
        std::sync::Arc::new(um_console::runtime::FailingRuntimeFacts),
        |_| {},
    );
    let response = get(console.addr, "/api/console/services");
    assert_eq!(response.status, 502);
    assert_eq!(
        response.json(),
        json!({"error": "runtime status unavailable"})
    );
}

#[test]
fn summary_is_stable_across_requests() {
    let temp = temp();
    let console = start_console(&temp);
    let first = get(console.addr, "/api/summary").json();
    let second = get(console.addr, "/api/summary").json();
    assert_eq!(first["role"], second["role"]);
    assert_eq!(first["assembly"], second["assembly"]);
    assert_eq!(first["services"], second["services"]);
    assert_eq!(first["_generated_epoch"], second["_generated_epoch"]);
}

